"""Deterministic parameter search over original Cartesian controllers."""
import json,time,os
import numpy as np
import mw_tool

class Controller:
 def __init__(self):self.s=mw_tool.Session()
 def run(self,p,save=None):
  s=self.s;s.reset()
  def move(target,n,speed,gain=20):
   target=np.asarray(target,float)
   for i in range(n):
    error=target-s.env.tcp_center
    s.step(np.r_[np.clip(gain*error,-speed,speed),1.])
    if np.linalg.norm(error)<p['tol'] and i>5:break
  move([p['side_x'],p['first_y'],p['first_z']],p['first_n'],p['first_speed'],p['route_gain'])
  move([p['side_x'],p['low_y'],p['low_z']],p['low_n'],p['low_speed'],p['route_gain'])
  move([p['side_x'],p['back_y'],p['low_z']],p['side_n'],p['side_speed'],p['route_gain'])
  move([p['entry_x'],p['back_y'],p['low_z']],p['entry_n'],p['entry_speed'],p['route_gain'])
  pre=len(s.actions);goal=s.target_pos
  for i in range(140):
   obj=s.obs[4:7];err=goal[:2]-obj[:2]
