import json,time,numpy as np
from controller_search import Controller

class StableController(Controller):
 def run(self,p,save=None):
  s=self.s;s.reset()
  def move(target,n,speed,gain):
   target=np.asarray(target,float)
   for i in range(n):
    err=target-s.env.tcp_center;s.step(np.r_[np.clip(gain*err,-speed,speed),1])
    if np.linalg.norm(err)<p['tol'] and i>8:break
  move([p['xside'],p['first_y'],p['first_z']],p['first_n'],p['first_speed'],p['route_gain'])
  move([p['xside'],p['first_y'],p['low_z']],p['low_n'],p['low_speed'],p['route_gain'])
  move([p['xside'],p['yback'],p['low_z']],p['side_n'],p['side_speed'],p['route_gain'])
  move([p['entry_x'],p['yback'],p['low_z']],p['entry_n'],p['entry_speed'],p['route_gain'])
  pre=len(s.actions);goal=s.target_pos
  for _ in range(p['push_n']):
   obj=s.obs[4:7];err=goal[:2]-obj[:2]
   target=np.array([obj[0]+np.clip(p['xgain']*err[0],-p['xcap'],p['xcap']),goal[1]+p['offset'],p['push_z']])
   s.step(np.r_[np.clip(p['push_gain']*(target-s.env.tcp_center),-p['push_cap'],p['push_cap']),1])
   if s.check()['obj_to_target']<p['switch_dist'] and np.linalg.norm(s.data.qvel[-2:])<p['switch_vel']:break
  pushn=len(s.actions)-pre
  for _ in range(p['align_n']):
   err=goal[:2]-s.obs[4:6]
   action=np.r_[np.clip(p['align_gain']*err-p['vel_gain']*s.data.qvel[-2:],-p['align_cap'],p['align_cap']),np.clip(15*(p['push_z']-s.env.tcp_center[2]),-.2,.2),1]
   s.step(action)
  for _ in range(p['release_n']):s.step([0,p['release_y'],p['release_z'],1])
  for _ in range(p['hold_n']):s.step([0,0,0,-1])
  r={'steps':len(s.actions),'dist':s.check()['obj_to_target'],'success':s.check()['success'],'pre':pre,'pushn':pushn,'vel':float(np.linalg.norm(s.data.qvel[-2:])),'params':p}
  if save and r['success'] and r['steps']<=500:s.save_trajectory(path=save,meta=r)
  return r

