def eval(c,p):
 r=c.run(p);A=np.array(c.s.actions).copy();r['actions']=A
 if not(r['success'] and r['steps']<=450 and r['dist']<.001 and r['vel']<.0001):r['score']=1e9;return r
 distances=[]
 for seed in [7773,26086,40052]:
  rng=np.random.default_rng(seed)
  for _ in range(3):
   c.s.replay(np.clip(A+rng.normal(0,.01,A.shape),-1,1));distances.append(c.s.check()['obj_to_target'])
 r['noise_success']=sum(d<=.07 for d in distances);r['noise_max']=max(distances);r['noise_mean']=float(np.mean(distances))
 r['score']=r['noise_max']*100+r['noise_mean']*50+r['steps']*.005+r['dist']*100
 return r

