 for _ in range(p['n']):
  error=desired-s.obs[4:6];integ+=error*.0125
  s.step(np.r_[np.clip(p['kp']*error-p['kv']*s.data.qvel[-2:]+p['ki']*integ,-p['cap'],p['cap']),np.clip(p['kz']*(p['z']-s.env.tcp_center[2]),-.2,.2),1])
 for _ in range(p['release_n']):s.step([p['release_x'],p['release_y'],p['release_z'],1])
 for _ in range(p['hold_n']):s.step([0,0,0,-1])
 err=s.obs[4:6]-goal[:2]
 if save:
  meta={'tail':p,'bias':np.array(bias).tolist(),'error':err.tolist(),'steps':len(s.actions),'success':s.check()['success'],'dist':s.check()['obj_to_target']}
