  with open('/app/newton_best.json','w') as f:json.dump(meta,f)
 return err

bias=np.zeros(2);best=np.inf
for it in range(25):
 error=trial(bias);norm=np.linalg.norm(error)
 if norm<best:best=norm;trial(bias,True)
 print('ITER',it,'bias',bias,'error',error,'norm',norm,flush=True)
 if norm<1e-10:break
 h=max(2e-7,min(1e-5,norm*.4))
 J=np.column_stack([(trial(bias+np.eye(2)[j]*h)-trial(bias-np.eye(2)[j]*h))/(2*h) for j in range(2)])
 correction=np.linalg.lstsq(J,error,rcond=1e-6)[0]
 candidates=[]
 for scale in [1,.5,.25,-.5]:
